let drawer;

function setup() {
	const s = max(windowWidth, windowHeight)
	createCanvas(s, s)

	noFill();

	drawer = new MyDrawer();

	background(255);

}

function draw() {
	push();
	// scale(scaleRatio);

	drawer.draw();
	pop();
}

class MyDrawer {
	constructor() {
		this.drawingArea = {
			x: 0,
			y: 0,
			width: width,
			height: height,
		};
		this.lastArea = {
			x: 0,
			y: 0,
			width: width,
			height: height,
		};
		this.nextArea = {};
		this.wRatio = 1;
		this.hRatio = 1;
		this.step = 1;
		this.changing = false;

		this.g = get();
		this.changingDuration = 40;
		// this.drawingDuration = 80;
		this.setDrawingDuration();
		this.timer = this.drawingDuration;
	}

	setDrawingDuration() {
		this.drawingDuration = floor(
			min(this.drawingArea.width, this.drawingArea.height) / 5
		);
	}

	draw() {
		// print(this.timer);
		if (this.changing) {
			background(255);
			// 變形狀態
			// background(255);
			const ratio = easeInOutCubic(1 - this.timer / this.changingDuration);
			if (this.step % 4 == 2) {
				// 往左邊縮小
				const x = lerp(this.lastArea.x, this.nextArea.x, ratio);
				const y = lerp(this.lastArea.y, this.nextArea.y, ratio);
				const gWidth = lerp(
					this.lastArea.width,
					this.lastArea.width * (this.nextArea.height / this.lastArea.height),
					ratio
				);
				const gHeight = lerp(this.lastArea.height, this.nextArea.height, ratio);
				image(this.g, x, y, gWidth, gHeight);
			} else if (this.step % 4 == 3) {
				// 往上面縮小
				var x = lerp(this.lastArea.x, this.nextArea.x, ratio);
				var y = lerp(this.lastArea.y, this.nextArea.y, ratio);
				var gWidth = lerp(this.lastArea.width, this.nextArea.width, ratio);
				var gHeight = lerp(
					this.lastArea.height,
					this.lastArea.height * (this.nextArea.width / this.lastArea.width),
					ratio
				);
				image(this.g, x, y, gWidth, gHeight);
			} else if (this.step % 4 == 0) {
				// 往右邊縮小
				var x = lerp(
					this.lastArea.x,
					this.nextArea.x + this.nextArea.height,
					ratio
				);
				var y = lerp(this.lastArea.y, this.nextArea.y, ratio);
				var gWidth = lerp(
					this.lastArea.width,
					this.nextArea.width - this.nextArea.height,
					ratio
				);
				var gHeight = lerp(this.lastArea.height, this.nextArea.height, ratio);
				image(this.g, x, y, gWidth, gHeight);
			} else if (this.step % 4 == 1) {
				// 往下面縮小
				var x = lerp(this.lastArea.x, this.nextArea.x, ratio);
				var y = lerp(
					this.lastArea.y,
					this.nextArea.y + this.nextArea.width,
					ratio
				);
				var gWidth = lerp(this.lastArea.width, this.nextArea.width, ratio);
				var gHeight = lerp(
					this.lastArea.height,
					this.nextArea.height - this.nextArea.width,
					ratio
				);
				image(this.g, x, y, gWidth, gHeight);
			}
		} else {
			// 繪製狀態

			// stroke(0, 0, 0, 0);
			//--------遮罩開始
			stroke(255);
			rect(
				this.drawingArea.x,
				this.drawingArea.y,
				this.drawingArea.width,
				this.drawingArea.height
			);
			stroke(0);

			push();
			drawingContext.clip();
			//-------遮罩結束

			// 旋轉
			push();
			translate(this.drawingArea.x, this.drawingArea.y);
			translate(this.drawingArea.width / 2, this.drawingArea.height / 2);
			if (this.step % 4 == 1) {
				//圓心在右下
			} else if (this.step % 4 == 2) {
				//圓心在左下
				rotate(PI / 2);
			} else if (this.step % 4 == 3) {
				rotate(PI);
			} else if (this.step % 4 == 0) {
				rotate((PI * 3) / 2);
			}

			translate(-this.drawingArea.width / 2, -this.drawingArea.height / 2);

			var ratio = 1 - this.timer / this.drawingDuration;
			for (let i = 0; i < 200; i++) {
				const angle =
					lerp(PI - 0.1, (PI * 3) / 2 + 0.1, ratio) + random(-0.15, 0.15);
				strokeWeight(this.drawingArea.width * 0.005 * randomGaussian(1, 0.3));
				blendMode(MULTIPLY)
				const r = 1 - random(random(random()));
				var x =
					this.drawingArea.width + cos(angle) * this.drawingArea.width * r;
				var y =
					this.drawingArea.height + sin(angle) * this.drawingArea.height * r;
				stroke(0,255,255)
				point(x, y);
				stroke(255,0,255)
				const rand1 = random(-this.drawingArea.width*0.005,this.drawingArea.width*0.005)
				const rand2 = random(-this.drawingArea.width*0.005,this.drawingArea.width*0.005)
				point(x + rand1, y + rand2);
				stroke(255,255,0)
				const rand3 = random(-this.drawingArea.width*0.005,this.drawingArea.width*0.005)
				const rand4 = random(-this.drawingArea.width*0.005,this.drawingArea.width*0.005)
				point(x + rand3, y + rand4);
			}

			pop();

			// circle(
			//   random(this.drawingArea.x, this.drawingArea.x + this.drawingArea.width),
			//   random(
			//     this.drawingArea.y,
			//     this.drawingArea.y + this.drawingArea.height
			//   ),
			//   random(30, 50)
			// );

			pop();
		}

		// print(this.timer);

		this.timer--;
		if (this.timer == 0) {
			if (!this.changing) {
				//進入變形狀態的瞬間
				this.timer = this.changingDuration;
				if (this.wRatio > this.hRatio) {
					// 橫比例
					const gX = 0;
					const gY =
						(height * ((this.wRatio - this.hRatio) / 2)) / this.wRatio;
					this.lastArea = {
						x: gX,
						y: gY,
						width: width,
						height: height * (this.hRatio / this.wRatio),
					};
					this.g = get(
						this.lastArea.x,
						this.lastArea.y,
						this.lastArea.width,
						this.lastArea.height
					);
					// background(255);
					// rect(gX, gY, width, height * (this.hRatio / this.wRatio));
					this.hRatio += this.wRatio;
					// 計算下一個主區域
					this.nextArea = {
						// 下個主區域會是直比例
						x: (width * ((this.hRatio - this.wRatio) / 2)) / this.hRatio,
						y: 0,
						width: width * (this.wRatio / this.hRatio),
						height: height,
					};
				} else {
					//直比例
					var gX =
						(width * ((this.hRatio - this.wRatio) / 2)) / this.hRatio;
					var gY = 0;
					this.lastArea = {
						x: gX,
						y: gY,
						width: width * (this.wRatio / this.hRatio),
						height: height,
					};
					this.g = get(
						this.lastArea.x,
						this.lastArea.y,
						this.lastArea.width,
						this.lastArea.height
					);
					// background(255);
					// rect(gX, gY, width * (this.wRatio / this.hRatio), height);
					this.wRatio += this.hRatio;
					// 計算下一個主區域
					this.nextArea = {
						// 下個主區域會是橫比例
						x: 0,
						y: (height * ((this.wRatio - this.hRatio) / 2)) / this.wRatio,
						width: width,
						height: height * (this.hRatio / this.wRatio),
					};
				}

				// print("step" + this.step);
				// print("w:" + this.wRatio);
				// print("h:" + this.hRatio);

				// push();
				// stroke("blue");
				// rect(
				//   this.nextArea.x,
				//   this.nextArea.y,
				//   this.nextArea.width,
				//   this.nextArea.height
				// );
				// pop();

				// 找到下一個繪製區域
				if (this.step % 4 == 1) {
					//右
					this.drawingArea = {
						x: this.nextArea.x + this.nextArea.width - this.nextArea.height,
						y: this.nextArea.y,
						width: this.nextArea.height,
						height: this.nextArea.height,
					};
					// rect()
				} else if (this.step % 4 == 2) {
					//下
					this.drawingArea = {
						x: this.nextArea.x,
						y: this.nextArea.y + this.nextArea.height - this.nextArea.width,
						width: this.nextArea.width,
						height: this.nextArea.width,
					};
				} else if (this.step % 4 == 3) {
					//左
					this.drawingArea = {
						x: this.nextArea.x,
						y: this.nextArea.y,
						width: this.nextArea.height,
						height: this.nextArea.height,
					};
				} else if (this.step % 4 == 0) {
					//上
					this.drawingArea = {
						x: this.nextArea.x,
						y: this.nextArea.y,
						width: this.nextArea.width,
						height: this.nextArea.width,
					};
				}
				this.step++;
			} else {
				// 進入繪製狀態的瞬間
				this.setDrawingDuration();
				this.timer = this.drawingDuration;
				// print(this.timer);
			}
			this.changing = !this.changing;
		}
	}
}

function easeInOutCubic(x) {
	return x < 0.5 ? 4 * x * x * x : 1 - Math.pow(-2 * x + 2, 3) / 2;
}
